(function () {
window.AINOW = window.AINOW || {};
var __exports = AINOW['data/data-creative'] = AINOW['data/data-creative'] || {};
// AINOW Creative Writing Library - 100 Prompts
const creativePrompts = [

    // --- UNRELIABLE NARRATORS & VOICE (1-8) ---
    {"id":"crt-1","title":"Unreliable Narrator: The Forensic Accountant","prompt":"You are a master fiction writer and creative writing professor. Write the opening 500 words of a psychological thriller short story featuring an unreliable narrator named Meredith Voss, a 41-year-old forensic accountant who has just discovered what she believes is embezzlement evidence against her husband of 14 years — but the reader should gradually sense through subtle inconsistencies that Meredith herself may be misremembering or fabricating. The opening should: establish Meredith's voice as precise, methodical, and self-assured (she is a numbers person who trusts evidence), introduce the inciting discovery through a specific detail (a wire transfer to an account she doesn't recognize), plant two subtle unreliability signals that a careful reader will notice on a second read but not the first, and end on a line that feels like certainty but is actually a question. Write in close third person. Prose style: taut, precise, with short sentences that accelerate in the final paragraph.","tags":["creative-writing","fiction","thriller","unreliable-narrator"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

    {"id":"crt-2","title":"The Dementia Narrator","prompt":"You are an expert literary fiction writer. Write a 600-word short story excerpt narrated by 78-year-old Harriet Bloom, a retired schoolteacher experiencing early-stage dementia. The story takes place over a single afternoon in her garden. The challenge: make the prose beautiful and lyrical even as it subtly fragments — Harriet mistakes her daughter for her late sister twice, describes the same rosebush as if seeing it for the first time on consecutive pages, and holds a conversation with her deceased husband that she believes is happening now. The reader should feel both the tragedy and the strange, private grace of her perception. Never play the condition for horror or pity — aim for tenderness. Use present tense throughout.","tags":["creative-writing","literary-fiction","voice","character"],"author":"AINOW","created":"2024-02-15T10:05:00Z","featured":false},

    {"id":"crt-3","title":"First-Person Villain Manifesto","prompt":"You are a literary fiction writer with expertise in moral complexity. Write a 500-word interior monologue from the point of view of Marcus Hale, a 52-year-old city councilman who has just voted to demolish a community garden to make way for a luxury development he has a financial stake in. Marcus does not think of himself as corrupt. Write his full internal justification: the way he reframes his self-interest as pragmatism, the memory he returns to of his own childhood poverty to explain why wealth-creation is virtue, the specific bureaucratic language he uses to soothe himself. The monologue should be chilling precisely because it is coherent. No mustache-twirling. Marcus should sound, to himself, entirely reasonable.","tags":["creative-writing","fiction","character","voice","villain"],"author":"AINOW","created":"2024-02-15T10:10:00Z","featured":false},

    {"id":"crt-4","title":"Dual POV: Same Scene, Opposing Truths","prompt":"You are a fiction writing workshop instructor. Write the same five-minute argument between two siblings — Nora, 38, and Daniel, 44 — in two back-to-back versions: first from Nora's close-third perspective, then from Daniel's. The argument is about whether to sell their late mother's house. The facts of the scene (the words spoken, the room they are in, the time of day) must remain identical in both versions. What changes is emphasis, interpretation, what each character notices, and what each treats as the most important moment. The exercise should demonstrate to a writing student how POV is not just a camera angle but an act of editorial selection. After both scenes, add a 100-word craft note explaining what specific technique you used in each version.","tags":["creative-writing","craft","POV","character","workshop"],"author":"AINOW","created":"2024-02-15T10:15:00Z","featured":true},

    {"id":"crt-5","title":"Voice Transplant: Rewrite in a Distinct Register","prompt":"[Paste your draft scene or character description]\n\nYou are a prose style specialist and literary editor. Take the passage above and rewrite it three times, each time transplanting it into a radically different narrative voice:\n1. A detached, clinical voice — no adjectives of feeling, only observed behavior and physical fact, as if written by a scientist documenting a specimen.\n2. A maximalist Southern Gothic voice — sprawling sentences, theological overtones, decay and beauty intertwined, heat in every noun.\n3. A spare, Carver-esque minimalist voice — submerged emotion, dialogue that circles what is never said, white space doing the work.\nAfter each rewrite, add one sentence explaining the core technique that defines that voice. The rewrites should each be 150–200 words.","tags":["creative-writing","craft","voice","style","workshop"],"author":"AINOW","created":"2024-02-15T10:20:00Z","featured":false},

    {"id":"crt-6","title":"Child Narrator: Adult Horror Through Innocent Eyes","prompt":"You are a literary horror writer with expertise in restraint and indirection. Write a 500-word short story narrated by seven-year-old Maya, who is describing the weeks since her father 'went away on a trip.' Maya does not understand what has happened — the adults around her speak in clipped, guarded sentences, her grandmother has moved in, there are too many casseroles in the refrigerator. Write Maya's narration in a voice that is genuinely, authentically that of a curious, bright seven-year-old — she notices the wrong things, takes comfort in small rituals, believes the explanations she is given. The horror must arise entirely from what the adult reader understands that Maya does not. Never step outside Maya's perspective. No dramatic irony through adult diction. The final line should be something Maya considers good news.","tags":["creative-writing","horror","literary-fiction","voice","child-narrator"],"author":"AINOW","created":"2024-02-15T10:25:00Z","featured":false},

    {"id":"crt-7","title":"Epistolary Voice: The Letter Never Sent","prompt":"You are a literary fiction writer specializing in epistolary form. Write three unsent letters — each approximately 250 words — from the same character: Delia Park, a 61-year-old Korean-American restaurateur in Cleveland, Ohio. The three letters are addressed to: (1) her estranged daughter, written the night the daughter left for good; (2) the building she is about to lose to foreclosure, addressed directly as 'you'; (3) the version of herself at 22 who emigrated from Busan. Each letter should feel like a distinct voice within the same person — grief, anger, and tenderness operating at different registers. The letters should not be sentimental. They should be true.","tags":["creative-writing","literary-fiction","voice","epistolary","character"],"author":"AINOW","created":"2024-02-15T10:30:00Z","featured":false},

    {"id":"crt-8","title":"The Obsessive Narrator: Cataloguing as Character","prompt":"You are a fiction writer and writing craft expert. Write a 400-word opening to a short story in which the narrator's obsessiveness is revealed entirely through what they choose to catalogue and how. The narrator, Thomas Ingram, a 35-year-old watch repairman, is waiting in the emergency room after his wife has been taken in for tests. He cannot bring himself to think about the medical situation directly. Instead, he inventories: the number of ceiling tiles with water stains (seven), the specific fonts used on the signs, the quality of the weld on the chair legs, the winding mechanisms visible through the glass face of the clock across the room — and whether it is a reliable movement or not. Through this inventory alone, reveal Thomas's terror, his love, and the professional habit of mind that is simultaneously his greatest comfort and his deepest limitation.","tags":["creative-writing","fiction","voice","character","craft"],"author":"AINOW","created":"2024-02-15T10:35:00Z","featured":false},

    // --- CHARACTER DEVELOPMENT (9-17) ---
    {"id":"crt-9","title":"The Character Wound Architecture","prompt":"You are a fiction writing coach with expertise in character psychology. Develop the full psychological architecture for a protagonist named Sylvie Marchetti, 34, a trauma surgeon in Chicago who is also a compulsive gambler. Build her in three layers:\n\nLayer 1 — The Wound: Identify the specific formative event (not a generic tragedy but a particular, concrete moment, around age 9–12) that created her core false belief about herself.\n\nLayer 2 — The Adaptive Behavior: Explain how both her career and her gambling are actually the same response to that wound — the same psychological need expressed in two different arenas.\n\nLayer 3 — The Contradiction That Makes Her Human: Identify one quality she genuinely possesses that directly contradicts her wound narrative, and explain why she cannot yet see it in herself.\n\nFinish with a 'Inciting scene' suggestion: the moment in Chapter 1 where the wound and the external plot collide for the first time.","tags":["creative-writing","character","craft","psychology","fiction"],"author":"AINOW","created":"2024-02-15T10:40:00Z","featured":true},

    {"id":"crt-10","title":"Secondary Character Who Steals the Scene","prompt":"You are a fiction writer and screenplay consultant. Create a fully realized secondary character for a heist thriller. The character is Reggie Oduya, 58, a retired safe-cracker who is being pulled back in for one last job. He appears in only four scenes. Your task: make him so specific, so alive with contradictions and private logic, that readers will wish the book were about him. Define: (1) His one physical habit that appears in every scene and means something different each time; (2) The single secret he is protecting that the protagonist never fully learns; (3) The specific, non-generic way he speaks — not an accent but a grammatical habit or a repertoire of references that mark him as exactly himself; (4) The moment in scene three where he does something the protagonist does not understand, and the reason behind it that the reader only glimpses.","tags":["creative-writing","character","fiction","craft","thriller"],"author":"AINOW","created":"2024-02-15T10:45:00Z","featured":false},

    {"id":"crt-11","title":"Character Arc in Six Sentences","prompt":"You are a master storyteller and fiction writing professor. Demonstrate the complete emotional arc of a character using exactly six sentences — one sentence per stage of transformation. The character is Joaquin Reyes, a 29-year-old undocumented immigrant working as a sous chef in Miami who discovers his head chef has been taking credit for his recipes. The six sentences must each carry: (1) the character's mistaken belief about the world; (2) the inciting disruption; (3) the moment of resistance; (4) the failed attempt to solve it with the old worldview; (5) the crisis that forces a new understanding; (6) the transformed person taking one concrete action they could not have taken in sentence one. After writing the six sentences, add a 150-word craft note explaining how you embedded each of the six functions without sacrificing the prose quality.","tags":["creative-writing","character","craft","arc","workshop"],"author":"AINOW","created":"2024-02-15T10:50:00Z","featured":false},

    {"id":"crt-12","title":"The Antagonist's Legitimate Grievance","prompt":"You are a literary fiction writer with expertise in morally complex antagonists. Construct the complete, legitimate, non-cartoonish grievance of antagonist Dr. Priya Sundaram, a 47-year-old epidemiologist who has been the villain of a medical thriller — she has been withholding information about a vaccine trial from the public. The reader has been positioned against her. Now write her full case: the specific institutional betrayals she suffered over twenty years, the actual data she is protecting people from misinterpreting, and the one moment — a specific meeting, a specific conversation — where she made the decision that crossed the line. Her grievance must be legitimate enough that a thoughtful reader, having read only her version, would sympathize. Her crossing-the-line must be understandable without being excusable. No redemption arc required — this is a study in how good people authorize wrong actions.","tags":["creative-writing","character","antagonist","fiction","craft"],"author":"AINOW","created":"2024-02-15T10:55:00Z","featured":false},

    {"id":"crt-13","title":"Dialogue That Builds a Relationship in Three Exchanges","prompt":"You are a fiction writer and dialogue specialist. Write three short exchanges between two characters — marine biologist Dr. Aiko Tanaka, 41, and her new research assistant, Ben Osei, 24 — that take place over three different days. Each exchange should be no more than eight lines of dialogue. Through these three exchanges alone (no narration, no interior monologue, no stage directions beyond minimal action beats), the reader should understand: the specific dynamic of authority and deference between them, the moment it begins to shift, and that by the third exchange something unspoken has passed between them that neither will acknowledge. The subject of all three conversations is the research — plankton die-offs in the Coral Sea. The relationship is the subtext. Write the three exchanges, then add a 100-word craft note on what specific technique in each exchange does the emotional work.","tags":["creative-writing","dialogue","craft","character","fiction"],"author":"AINOW","created":"2024-02-15T11:00:00Z","featured":false},

    {"id":"crt-14","title":"The Character Who Cannot Lie But Hides Everything","prompt":"You are a literary fiction writer. Write a 500-word scene in which the protagonist, Vera Lindt, a 50-year-old German-born archivist in Prague, is questioned by her nephew about the whereabouts of a document. Vera never lies — this is established early as a core fact about her, almost a compulsion. But she also never reveals the truth. Show, through her word choices, her physical behavior, and what she chooses to answer versus what she chooses not to answer, how a person can be constitutionally honest and still withhold everything that matters. The nephew is not stupid. The scene should feel like a chess match that Vera wins by playing a game her opponent does not know they are in.","tags":["creative-writing","fiction","character","dialogue","craft"],"author":"AINOW","created":"2024-02-15T11:05:00Z","featured":false},

    {"id":"crt-15","title":"Backstory That Never Appears on the Page","prompt":"You are a fiction writing coach. Develop 800 words of detailed backstory for Callie Drummond, 33, the protagonist of a contemporary literary novel — backstory that will never appear directly in the novel itself, but will invisibly shape every scene she is in. Cover: the specific emotional texture of her childhood in a rural Montana trailer park with a mother who was brilliant and self-destructive; the friendship at 16 that defined her understanding of loyalty; the scholarship to Wellesley and the particular shame and pride of being the first in her family to attend college; the relationship at 28 that ended not dramatically but through gradual attrition. The backstory should be written as a character document for the author, not as prose for the reader. Be specific, concrete, and psychologically precise. End with a list of five ways this backstory will surface in her behavior without ever being stated.","tags":["creative-writing","character","craft","backstory","workshop"],"author":"AINOW","created":"2024-02-15T11:10:00Z","featured":false},

    {"id":"crt-16","title":"Grief Expressed Through Hyperspecific Behavior","prompt":"You are a literary fiction writer specializing in the indirect expression of emotion. Write a 400-word scene in which recently widowed Frank Costas, 67, a retired electrician in Brockton, Massachusetts, expresses his grief without once naming it or describing it directly — no tears, no chest-tightening, no 'he felt the familiar weight of loss.' Frank has come to the supermarket for the first time since his wife Elena died three weeks ago. His grief must be rendered entirely through his specific physical behaviors and decisions in the produce section: what he puts in the cart, what he puts back, how long he stands in front of the olives. The reader should be devastated. The word 'grief' (or 'sad,' 'loss,' 'mourning') should not appear.","tags":["creative-writing","literary-fiction","character","craft","emotion"],"author":"AINOW","created":"2024-02-15T11:15:00Z","featured":true},

    {"id":"crt-17","title":"The Character Interview: 20 Questions That Unlock a Novel","prompt":"You are a fiction writing coach with expertise in character discovery. I am writing a novel featuring a protagonist named [character name and brief description — e.g., 'Amara, 29, a refugee from Eritrea now working as a nurse in Minneapolis']. Conduct a deep-dive character interview of 20 questions. Do not ask generic questions like 'What is their biggest fear?' Instead, ask specific, unexpected, generative questions — the kind that force a writer to discover something they did not know about their character. Examples of the register I want: 'What does your character do when they are alone and slightly bored that they would be embarrassed if anyone saw?' or 'What is the last lie they told that they still feel was justified?' After each question, provide a 1–2 sentence note on what aspect of character the question is designed to excavate.\n\n[Paste your character description]","tags":["creative-writing","character","workshop","craft","development"],"author":"AINOW","created":"2024-02-15T11:20:00Z","featured":false},

    // --- WORLDBUILDING (18-26) ---
    {"id":"crt-18","title":"The Economy of a Fantasy City","prompt":"You are a fantasy worldbuilding specialist and economic historian. Design the complete economy of Vethara, a walled city of 80,000 people in a secondary-world fantasy setting where magic is real but rare, expensive, and controlled by a guild. Answer the following, with specificity and internal logic: (1) What are the city's three primary exports and why those three? (2) What is the relationship between the Mages' Guild and the merchant class — who holds more real power and why? (3) What does poverty look like in Vethara — not as an abstract, but in the daily life of a specific fictional family in the lowest economic tier? (4) What is the one economic tension that is about to destabilize the city? (5) What everyday transaction — buying bread, paying a toll, hiring labor — reveals something true about power in this city? Make the economy feel lived-in, not constructed.","tags":["creative-writing","worldbuilding","fantasy","craft","fiction"],"author":"AINOW","created":"2024-02-15T11:25:00Z","featured":false},

    {"id":"crt-19","title":"Ecology as Worldbuilding: A Self-Consistent Biome","prompt":"You are a science fiction worldbuilder with a background in ecology. Design a complete, self-consistent biome for a fictional planet called Oshen IV, a world with 1.2 Earth gravity, two small moons, and an axial tilt of 41 degrees that produces extreme seasons. Your biome must: (1) Describe the dominant photosynthetic organisms and explain their adaptation to the light spectrum of Oshen IV's orange dwarf star; (2) Design a food web with at least five trophic levels, naming specific organisms and their relationships; (3) Explain one evolutionary arms race between two specific organisms and what that looks like in observable behavior; (4) Describe how the extreme seasons shape the reproductive cycles of the dominant fauna; (5) Identify the keystone species — the one organism whose removal would cause cascading collapse — and explain why. The biome should feel like it evolved, not like it was designed.","tags":["creative-writing","worldbuilding","sci-fi","ecology","fiction"],"author":"AINOW","created":"2024-02-15T11:30:00Z","featured":false},

    {"id":"crt-20","title":"Religion That Shapes a Civilization","prompt":"You are a literary worldbuilder and anthropologist of religion. Design a complete, non-Western-derived religion for a fictional civilization of seafarers called the Verath. The religion must: (1) Have a theology that is internally consistent and grows organically from the seafaring life — the sea is central but not simplified into 'the sea god'; (2) Include a specific creation narrative that explains why the Verath believe mortality is a gift rather than a punishment; (3) Describe three ritual practices — one daily, one annual, one once-in-a-lifetime — that reveal something true about the civilization's values; (4) Explain the heresy that most threatens the orthodoxy and why it appeals to the young; (5) Show how the religion shapes architecture, family structure, and the treatment of outsiders. Do not model this on any single real-world religion. The goal is genuine invention.","tags":["creative-writing","worldbuilding","culture","religion","fantasy"],"author":"AINOW","created":"2024-02-15T11:35:00Z","featured":true},

    {"id":"crt-21","title":"The City That Feels Real: Sensory Atlas","prompt":"You are a literary fiction writer and urban geographer. Create a sensory atlas for a fictional city called Marova — a Mediterranean port city of 300,000 people in a contemporary secondary world. The atlas should have five entries, one for each sense, and each entry should be 150–200 words. The smell entry is not 'salt and fish' — it is specific: the smell of the Kevara district on a Tuesday morning in August, which includes the diesel from the fish auction, the cardamom from the coffee seller on the corner of the market, and the particular chemical note of the water reclamation plant two kilometers upwind when the sea breeze shifts. Every detail should feel observed, not invented. When you are done, a reader should feel they have actually been to Marova. Add a 100-word note on how this kind of sensory specificity functions in literary fiction.","tags":["creative-writing","worldbuilding","craft","setting","fiction"],"author":"AINOW","created":"2024-02-15T11:40:00Z","featured":false},

    {"id":"crt-22","title":"Political System Built on a Lie","prompt":"You are a political fiction writer and worldbuilder. Design the complete political structure of the Confederation of Talaan, a fictional nation whose entire constitutional order rests on a founding myth that the ruling class knows to be false: the myth that the four founding clans signed a peaceful compact in the year 412. In fact, two of the clans were coerced through violence. Describe: (1) How the myth is maintained — the specific institutions, rituals, and educational practices that reproduce it; (2) Who knows the truth and how they carry that knowledge; (3) The political faction that has recently discovered documentary evidence of the lie and the three factions debating what to do with it; (4) How this political situation would play out differently in a fantasy novel vs. a political thriller. Make the Confederation feel like a real, fractured, functioning state.","tags":["creative-writing","worldbuilding","politics","fiction","craft"],"author":"AINOW","created":"2024-02-15T11:45:00Z","featured":false},

    {"id":"crt-23","title":"Technology That Changed Everything — But Not How You'd Expect","prompt":"You are a science fiction worldbuilder with expertise in second-order effects. In your fictional near-future setting, a technology has been invented that allows perfect, permanent memory recall for any human who receives a simple procedure. Explore not the obvious first-order effects but the unexpected second-order social consequences: (1) How has the institution of marriage changed when forgetting is no longer possible? (2) What has happened to the legal system, specifically the concept of reasonable doubt? (3) Describe the new class divide — not between those who have the procedure and those who don't, but the surprising social hierarchy that has emerged between those who had it at different ages; (4) What new art form has emerged in response to the loss of forgetting as a human experience? (5) What does nostalgia mean in this world? Write each section as 150 words of narrative worldbuilding, not bullet points.","tags":["creative-writing","worldbuilding","sci-fi","speculative-fiction","craft"],"author":"AINOW","created":"2024-02-15T11:50:00Z","featured":false},

    {"id":"crt-24","title":"The Villain's Homeland: Worldbuilding From the Other Side","prompt":"You are a fantasy worldbuilder specializing in moral complexity. In a conventional fantasy novel, the dark empire of Drath'Kol is the enemy civilization — oppressive, militaristic, feared. Your task: write a 600-word worldbuilding document from the perspective of a Drath'Koli historian writing for a domestic audience. In their telling: explain why Drath'Kol's expansion was defensive, not aggressive (be specific — name the earlier conflict, the border incident, the diplomatic failure); describe what life in Drath'Kol actually looks like for a middle-class family (not propaganda, but the genuine texture of daily life that a citizen would recognize as true); identify one thing Drath'Kol genuinely does better than the 'heroic' civilization the protagonist comes from. The goal is a worldbuilding exercise that forces writers to question whose story they are telling.","tags":["creative-writing","worldbuilding","fantasy","perspective","craft"],"author":"AINOW","created":"2024-02-15T11:55:00Z","featured":false},

    {"id":"crt-25","title":"Language as Culture: Designing What a Society Cannot Say","prompt":"You are a speculative fiction writer and linguistics enthusiast. Design a constructed language fragment for a fictional society with a specific cultural truth embedded in its grammar. The society is the Keth, a nomadic steppe people. The cultural truth: the Keth make no grammatical distinction between past and future tense — only between things that happened to one person versus things that happened to a group. Design: (1) Five specific examples of how this grammatical structure shapes how the Keth think about history and prophecy; (2) Three concepts that exist in English that the Keth language simply cannot express without a lengthy circumlocution — and explain what this reveals about their values; (3) One concept the Keth language expresses in a single word that requires a paragraph to explain in English; (4) A short three-line Keth proverb, with transliteration and a note on why it is untranslatable.","tags":["creative-writing","worldbuilding","linguistics","culture","speculative-fiction"],"author":"AINOW","created":"2024-02-15T12:00:00Z","featured":false},

    {"id":"crt-26","title":"The Haunted House as Character","prompt":"You are a literary horror writer and architectural historian. Design a specific, fully realized haunted house for a gothic horror novel — not a generic Victorian mansion but a building with a particular architectural history that has shaped its haunting. The house is Galloway Farm, a converted textile mill in Lancashire, England, built in 1841, expanded in 1889, converted to a private residence in 1962. Describe: (1) The architectural features that create dread — be specific about ceiling heights, sightlines, the placement of doors, the way sound travels; (2) The specific industrial history embedded in the building's bones that shapes what kind of haunting is possible here; (3) Three rooms, each with a distinct emotional register; (4) The one space in the house that is inexplicably comfortable, and why that is the most frightening thing about it. Write as a 600-word architectural character study.","tags":["creative-writing","horror","worldbuilding","setting","gothic"],"author":"AINOW","created":"2024-02-15T12:05:00Z","featured":false},

    // --- NARRATIVE STRUCTURE & PLOTTING (27-36) ---
    {"id":"crt-27","title":"The Five-Act Structure Applied to a Short Story","prompt":"You are a fiction writing professor and narrative theorist. Take the following premise and design a complete five-act short story structure for it, demonstrating that five-act structure is not only for plays and novels but can be compressed into 3,000 words of short fiction.\n\nPremise: A competitive chess player, Alena Ostrova, 38, discovers the night before a major tournament that her most trusted coach has been deliberately giving her subtly wrong advice for three years.\n\nFor each of the five acts, provide: (1) the narrative function of that act; (2) the specific scene that embodies it; (3) the emotional register for the reader; (4) the key information revealed. Then add a 150-word note on what the short story form forces you to compress or omit compared to a novel, and how that compression creates different emotional effects.","tags":["creative-writing","craft","structure","short-story","workshop"],"author":"AINOW","created":"2024-02-15T12:10:00Z","featured":false},

    {"id":"crt-28","title":"Non-Linear Chronology: The Jigsaw Structure","prompt":"You are a literary fiction writer and narrative structure specialist. Design a complete non-linear story structure for a 60,000-word novel called 'The Last Good Year.' The story covers three time periods: 1978 (when a family was intact and happy, in rural Vermont), 1994 (when the family fell apart, in Detroit), and 2019 (when the sole surviving member of the original family is contacted by a stranger). Your structural design must: (1) Determine in what order the time periods should be revealed and explain the emotional logic of that order; (2) Identify the 'pivot scenes' — the scenes that work as bridges between time periods and carry resonance in both directions; (3) Explain what information the reader must not have until chapter 20, and how you withhold it without cheating; (4) Design the final three chapters so that the last chapter is set in 1978 — and explain why that ending, arriving after all the knowledge the reader has accumulated, is more devastating than ending in 2019.","tags":["creative-writing","craft","structure","novel","workshop"],"author":"AINOW","created":"2024-02-15T12:15:00Z","featured":true},

    {"id":"crt-29","title":"The Subplot That Earns Its Place","prompt":"You are a fiction writing editor and story structure specialist. I am writing a thriller in which the main plot follows FBI agent Dana Chávez as she investigates a series of art forgeries connected to a money-laundering operation. The thriller needs a subplot that does real narrative work — not decoration, not comic relief, but a subplot that: (1) Introduces a thematic counterpoint to the main plot (identify what that theme is and why this subplot illuminates it); (2) Features a secondary character whose arc mirrors Dana's in a structurally productive way — describe that character and the mirroring; (3) Creates a scene in the third act where the subplot and main plot collide in a way neither could achieve alone; (4) Resolves in a way that changes how the reader understands the main plot's ending. Design the complete subplot arc, including three key scenes.","tags":["creative-writing","craft","structure","subplot","thriller"],"author":"AINOW","created":"2024-02-15T12:20:00Z","featured":false},

    {"id":"crt-30","title":"The Opening Line Masterclass","prompt":"You are a master fiction writer with deep expertise in first lines. Write 15 opening lines for 15 different fictional novels, each demonstrating a different technique for hooking a reader. The techniques must be genuinely distinct: not just 'different genres' but different rhetorical strategies — the line that creates immediate irony, the line that introduces a world-rule in passing, the line that begins mid-action with a specific sensory detail, the line that subverts a cliché in its second half, the line that makes an outrageous claim in an ordinary voice, and so on. After each line, write one sentence identifying the specific technique and what it creates in the reader. The lines should span multiple genres. All 15 should be lines you would actually use — no placeholders, no formulaic examples.","tags":["creative-writing","craft","opening-lines","technique","workshop"],"author":"AINOW","created":"2024-02-15T12:25:00Z","featured":false},

    {"id":"crt-31","title":"The Scene That Does Five Things at Once","prompt":"You are a fiction writing professor with expertise in narrative efficiency. Write a single 500-word scene that accomplishes exactly five narrative functions simultaneously: (1) advances the external plot; (2) reveals new character information that recontextualizes something the reader already knew; (3) establishes or deepens a theme without stating it; (4) builds or breaks a relationship between two characters; (5) delivers a piece of setting or world information that will matter later. The scene: Marco Velez, 44, a maritime lawyer, is having lunch with his estranged teenage daughter Cleo for the first time in two years. They are at a specific restaurant in Cartagena, Colombia. After the scene, annotate it — number each sentence or paragraph with which of the five functions it is performing (some will do multiple). This should function as a teaching document.","tags":["creative-writing","craft","scene","workshop","efficiency"],"author":"AINOW","created":"2024-02-15T12:30:00Z","featured":false},

    {"id":"crt-32","title":"Foreshadowing: Plant It, Don't Telegraph It","prompt":"You are a fiction writing expert and editor. Write a 400-word scene from the opening chapter of a mystery novel in which you plant exactly four pieces of foreshadowing for events that will occur in chapters 12, 18, 24, and the final chapter. The scene: Investigative journalist Petra Holst arrives at a small Norwegian coastal town to report on a series of fishing vessel disappearances. The foreshadowing must be completely invisible on a first read — nothing that causes the reader to pause, nothing that reads as a hint. On a second read, each element should feel inevitable. After the scene, write a 'Spoiler Key' that identifies each planted element and explains exactly what it foreshadows and why a first-time reader will not notice it. This should function as a masterclass in Chekhov's Gun technique.","tags":["creative-writing","craft","foreshadowing","mystery","technique"],"author":"AINOW","created":"2024-02-15T12:35:00Z","featured":false},

    {"id":"crt-33","title":"The Ending That Reframes Everything","prompt":"You are a master short story writer and narrative architect. Write the final 400 words of a literary short story — the ending only — that: (1) resolves the emotional arc of the protagonist completely; (2) reframes a detail introduced in the story's opening (which you will invent and describe briefly) so that its meaning is entirely different by the end; (3) ends on a final image rather than a final statement — show, don't explain; (4) leaves one significant question deliberately unanswered — not from incompleteness but because the unanswered question is the point. The story: Elena Vasquez, 52, a high school music teacher in Tucson, has just played piano at the funeral of the student she felt she failed. The ending should be devastating and redemptive at once — not one, not the other, both.","tags":["creative-writing","craft","endings","short-story","literary-fiction"],"author":"AINOW","created":"2024-02-15T12:40:00Z","featured":false},

    {"id":"crt-34","title":"The Scene Without a Protagonist","prompt":"You are a literary fiction writer specializing in ensemble and peripheral narration. Write a 500-word scene in which the protagonist of the novel — Irena Brandt, 45, a concert violinist — never appears. She is the subject of every conversation, but she is offstage. The scene takes place in the green room before her comeback performance after a two-year absence following a breakdown. Three people are in the room: her ex-husband, her manager, and a young violinist who was her student. Through their three separate conversations — none of which are with each other simultaneously — establish who Irena is, what happened two years ago, and what each of these three people needs from her return. The reader should feel Irena's absence as a presence.","tags":["creative-writing","craft","scene","literary-fiction","technique"],"author":"AINOW","created":"2024-02-15T12:45:00Z","featured":false},

    {"id":"crt-35","title":"The Ticking Clock: Building Dread Without Violence","prompt":"You are a thriller writer and tension specialist. Write a 600-word scene in which the protagonist, Yusuf Amir, a 39-year-old immigration lawyer, has exactly 90 minutes to find a specific document before his client is deported. There is no physical danger, no antagonist in the room, no chase. The tension must come entirely from: the specificity of the bureaucratic obstacle (describe the actual systems, the actual forms, the actual phone trees); the accumulating small failures that each cost time; and Yusuf's internal calculation of probability, which the reader can feel degrading in real time. By minute 60, the reader should be holding their breath. Write in present tense. No violence, no thriller conventions. Just bureaucracy, time, and what is at stake.","tags":["creative-writing","craft","tension","thriller","scene"],"author":"AINOW","created":"2024-02-15T12:50:00Z","featured":false},

    {"id":"crt-36","title":"The Scene Draft Analysis: What Is and Isn't Working","prompt":"[Paste your draft scene]\n\nYou are a fiction editor with 20 years of experience and a background as a published literary novelist. Analyze the draft scene above across five dimensions:\n\n1. MOMENTUM: Does the scene move? Identify the specific sentence or paragraph where momentum falters, and explain why.\n2. CHARACTER VOICE: Is the POV character's voice consistent and specific? Quote the moment(s) where it slips into generic.\n3. DIALOGUE: What is the subtext of each exchange? Is it doing narrative work or filling space? Quote the strongest and weakest line.\n4. SENSORY GROUNDING: Where is the reader unmoored from physical reality? What specific sensory detail is missing?\n5. FUNCTION: What does this scene do for the larger narrative? Is it earning its place?\n\nAfter the analysis, suggest three specific, concrete revisions — not direction but actual rewritten sentences or beats.","tags":["creative-writing","editing","craft","workshop","scene"],"author":"AINOW","created":"2024-02-15T12:55:00Z","featured":false},

    // --- GENRE FICTION (37-52) ---
    {"id":"crt-37","title":"Sci-Fi First Contact: The Linguist's Crisis","prompt":"You are a science fiction writer with expertise in hard science and linguistics. Write the opening 600 words of a first-contact science fiction short story from the perspective of Dr. Sophia Wen, 44, a xenolinguist, who is the first human being to make a potentially communicative response from the alien vessel that has been in orbit for eleven days. The story must: ground the science of communication in actual linguistic theory (not telepathy, not translation devices, not convenient humanoid speech); dramatize the internal tension between scientific caution and the human need for meaning-making; include one specific detail about the alien signal that is genuinely strange and that Wen has not been able to explain; end with Wen sending a response that she believes is correct but cannot verify — and the reader should feel the weight of that uncertainty.","tags":["creative-writing","sci-fi","linguistics","first-contact","fiction"],"author":"AINOW","created":"2024-02-15T13:00:00Z","featured":true},

    {"id":"crt-38","title":"Fantasy: The Magic System Stress Test","prompt":"You are a fantasy writer and magic system designer. Design a complete 'hard magic' system for a fantasy world in which the power source is the practitioner's own accumulated memories — every spell consumes a specific memory permanently. The system must pass the Brandon Sanderson stress test: a reader should be able to predict what a magic user can and cannot do, and feel the cost as genuinely costly. Specify: (1) The exact mechanics of how memory-cost is calculated (not vague — a fireball costs what, precisely?); (2) The social and psychological consequences for long-practicing mages; (3) The three-tier mastery system and what is sacrificed at each tier; (4) The one exploit in the system that makes it dangerous in ways the practitioners haven't fully understood yet; (5) Write a 250-word scene demonstrating the system under narrative pressure — a specific fight where the cost-benefit calculation is the dramatic engine.","tags":["creative-writing","fantasy","magic-system","craft","worldbuilding"],"author":"AINOW","created":"2024-02-15T13:05:00Z","featured":false},

    {"id":"crt-39","title":"Psychological Thriller: The Gaslighting Scene","prompt":"You are a psychological thriller writer specializing in interpersonal manipulation dynamics. Write a 500-word scene in which protagonist Claire Ashby, 36, begins to doubt her own memory during a seemingly ordinary dinner conversation with her partner, David. Claire believes she saw David at a location he denies being at. The scene must: show David's technique — not theatrical, not obviously sinister, but the small, precise, devastatingly plausible methods of someone skilled at this; show Claire's internal process as she searches for alternate explanations for her own certainty; include one moment where the reader is briefly uncertain alongside Claire (not because the reader doesn't know the truth, but because David is that good); end with Claire agreeing with David's version — and a single sensory detail that tells the reader she is wrong. Write in close third person, Claire's POV.","tags":["creative-writing","thriller","psychological","craft","fiction"],"author":"AINOW","created":"2024-02-15T13:10:00Z","featured":false},

    {"id":"crt-40","title":"Romance: The Almost-Kiss That Doesn't Happen","prompt":"You are a romance writer and tension specialist. Write a 500-word scene between Dara Flynn, 31, an Irish-American landscape architect in Portland, and Nate Osei, 34, a civil engineer she is collaborating with on a city park project — a scene in which the moment clearly comes for them to kiss, and it doesn't happen. The scene must: build the tension through their professional dynamic and specific shared intellectual enthusiasm for their project (not through conventional romance-novel heightening); make the not-happening feel more charged than a kiss would; give each character a specific, different reason for pulling back — neither of which should be stated, only shown through a behavioral choice; end with a piece of dialogue about the project that is entirely about something else. This scene should demonstrate why the best romantic tension in literary romance is often about restraint.","tags":["creative-writing","romance","tension","craft","fiction"],"author":"AINOW","created":"2024-02-15T13:15:00Z","featured":false},

    {"id":"crt-41","title":"Horror: Dread Without the Monster","prompt":"You are a literary horror writer in the tradition of Shirley Jackson and Mark Z. Danielewski. Write a 600-word scene in which the horror is entirely atmospheric — no monster, no supernatural event, no jump scare. The setting: a perfectly ordinary family home in suburban Ohio. The protagonist: Nina Farrow, 43, has returned to her childhood home to help her father sell it after her mother's death. The dread must come from: the specific wrongness of familiar objects in their familiar places; the way memory and present reality create uncanny dissonance; one recurring sensory detail that Nina cannot explain and does not try to; and the reader's sense that the wrongness is emanating from Nina herself rather than the house. No explanation, no resolution. The scene should end with Nina doing something completely ordinary that nonetheless feels like the worst thing she could possibly do.","tags":["creative-writing","horror","craft","atmosphere","fiction"],"author":"AINOW","created":"2024-02-15T13:20:00Z","featured":false},

    {"id":"crt-42","title":"Crime Fiction: The Detective Who Is Wrong","prompt":"You are a crime fiction writer specializing in subverted genre expectations. Write a 600-word scene in which Detective Inspector Ros Kaur, 48, lays out her theory of the crime to her sergeant — and she is completely, confidently wrong. The scene must function on two levels: on the surface, Kaur's theory should be plausible, even elegant, the product of genuine intelligence and experience; underneath, three specific details in the scene (in the physical environment of the interview room, in the case file on the table, in something the sergeant says) should allow a careful reader to see exactly where Kaur has gone wrong. The wrongness should not be stupidity — it should be the specific, believable wrongness of a brilliant person whose one blind spot happens to be precisely what this case requires. Do not reveal that Kaur is wrong. Let the reader do the work.","tags":["creative-writing","crime-fiction","craft","detective","mystery"],"author":"AINOW","created":"2024-02-15T13:25:00Z","featured":false},

    {"id":"crt-43","title":"Speculative Fiction: The Referendum","prompt":"You are a speculative fiction writer in the tradition of Ursula K. Le Guin. Write a 600-word short story set in a near-future democratic nation that is holding a referendum on whether to ban algorithmic personalization in all public media. The story should not be an essay — it is a story, with two specific characters in a specific moment: a mother, Priya, 51, and her daughter, Zara, 23, watching the results come in. Their political views must not be telegraphed as right or wrong. The story's job is to dramatize — through their specific conversation, their specific shared history, the specific television program they are watching — what is actually at stake in this question for two real human beings who love each other and disagree. The vote result should be revealed. The story should end in ambiguity about whether the result is good or bad.","tags":["creative-writing","speculative-fiction","political","craft","literary-fiction"],"author":"AINOW","created":"2024-02-15T13:30:00Z","featured":false},

    {"id":"crt-44","title":"Western: The Town That Knows What's Coming","prompt":"You are a literary western writer in the tradition of Cormac McCarthy and Paulette Jiles. Write the opening 500 words of a western short story in which the central narrative tension is not the approaching gunfight itself but the two hours before it arrives — the entire town of Resurrection, New Mexico, in 1887, going about its normal Tuesday afternoon with the full knowledge that Frank Dolan and his men are riding in at sunset. Show three different characters — not the protagonist, but peripheral townspeople — each choosing how to spend those two hours. The genius of the scene should be that each character's choice reveals a complete moral position. No shootout yet. Just Tuesday afternoon, and what people do with the time they have.","tags":["creative-writing","western","craft","genre-fiction","literary-fiction"],"author":"AINOW","created":"2024-02-15T13:35:00Z","featured":false},

    {"id":"crt-45","title":"Historical Fiction: The Witness Who Cannot Speak","prompt":"You are a historical fiction writer. Write a 600-word scene set in Warsaw, October 1944, during the aftermath of the Warsaw Uprising. The perspective is that of Zofia, a 17-year-old Polish girl who witnessed something in the first days of the uprising that she has told no one. She is now in a makeshift field hospital, helping tend to wounded fighters. She is not the protagonist of the larger novel — she is a secondary character — but this scene, in which she changes the dressings of a wounded man who does not know what she knows, must be one of the most important scenes in the book. The reader does not yet know what Zofia witnessed. Write the scene so that Zofia's knowledge shapes every word and gesture without being named. The reader should feel the weight of it pressing against her skin.","tags":["creative-writing","historical-fiction","craft","war","literary-fiction"],"author":"AINOW","created":"2024-02-15T13:40:00Z","featured":false},

    {"id":"crt-46","title":"Climate Fiction: The Inheritance","prompt":"You are a climate fiction writer and literary novelist. Write a 600-word scene set in 2067 in what was once coastal Louisiana. The scene is a conversation between Marguerite, 78, one of the last people to have lived in the pre-flood city, and her grandson Theo, 19, who has grown up in the inland relocation settlement. Theo has been offered a scholarship to study climate engineering in São Paulo and is asking his grandmother's permission — not legally but morally. Write the scene so that neither character represents a 'position' on climate change. Both are fully human. The emotional core is not about climate policy but about inheritance, loss, and what one generation owes another. The flooded coast must be present in the conversation without being the subject. Write in present tense.","tags":["creative-writing","climate-fiction","speculative-fiction","literary-fiction","craft"],"author":"AINOW","created":"2024-02-15T13:45:00Z","featured":false},

    {"id":"crt-47","title":"Domestic Noir: What the Kitchen Tells Us","prompt":"You are a domestic noir writer and literary crime novelist. Write a 500-word opening to a domestic noir in which the entire crime — a disappearance, a death, a deception — is communicated to the reader through the contents and condition of a kitchen. The protagonist, Helen Marsh, 44, has let herself into her sister's house using the spare key. Her sister Claire has not returned calls in six days. Helen stands in Claire's kitchen. What she finds there — not blood, not a note, but specific domestic details: what is in the refrigerator, what is on the counter, the state of the dish rack, one small thing that is wrong — should tell the reader everything. The scene should function as a masterclass in telling a story through objects and space. Helen should voice her own interpretations, some of which are correct and some of which are dangerously wrong.","tags":["creative-writing","domestic-noir","crime-fiction","craft","literary-fiction"],"author":"AINOW","created":"2024-02-15T13:50:00Z","featured":false},

    {"id":"crt-48","title":"Magical Realism: The Grief That Takes Physical Form","prompt":"You are a magical realist writer in the tradition of Gabriel García Márquez and Toni Morrison. Write a 500-word scene in which the grief of widower Aurelio Benítez, 60, a retired beekeeper in a small town in southern Mexico, takes a specific, impossible-but-accepted physical form in the world of the story. The magical element must: grow organically from the specific cultural and physical world of the story (beekeeping, small-town Mexico, Catholic tradition, the specific weight of a fifty-year marriage); be accepted as entirely normal by everyone in the story, including Aurelio; be specific — not a metaphorical cloud of sadness but a particular, concrete, describable thing; and function so that without it, the emotional truth of the grief could not be told. The scene should neither explain the magical element nor comment on it.","tags":["creative-writing","magical-realism","literary-fiction","craft","grief"],"author":"AINOW","created":"2024-02-15T13:55:00Z","featured":true},

    {"id":"crt-49","title":"Cozy Mystery: The Village with Secrets","prompt":"You are a cozy mystery writer with expertise in the British village tradition. Design the complete cast, setting, and inciting crime for a cozy mystery series set in Stourbridge Fen, a fictional village of 1,400 people in the Cambridgeshire fens. Your design must include: (1) The protagonist — not a retired detective, not a professional sleuth, but a specific civilian with a genuinely believable reason to get involved in village crimes; describe their personality, their day job, and their specific social position in the village; (2) Five recurring supporting characters, each with their own secret that is never resolved in any single book; (3) The first crime — specific, inventive, and achievable without the resources of a large criminal operation; (4) The red herring that makes the protagonist wrong for most of book one; (5) The feature of the village — geographical, social, or historical — that makes it a generator of crime plots.","tags":["creative-writing","cozy-mystery","craft","genre-fiction","series"],"author":"AINOW","created":"2024-02-15T14:00:00Z","featured":false},

    {"id":"crt-50","title":"Space Opera: The Scene That Makes the Empire Human","prompt":"You are a space opera writer specializing in moral complexity. Write a 600-word scene set aboard the flagship of the Terran Hegemony — the galactic empire that is the antagonist of your space opera series. The scene takes place in the ship's mess, not the bridge. Three officers of the Hegemony — a junior comms officer, a senior engineer, and a chaplain — are eating dinner during a long transit. They are not the Hegemony's face of evil. They are people doing a job. Through their specific conversation about entirely mundane matters — the food, a shipmate's promotion, the latest news from home — build the humanity of these people who serve an oppressive system, without excusing the system. By the end of the scene, the reader should feel the tragedy of ordinary human complicity in something terrible.","tags":["creative-writing","space-opera","sci-fi","craft","moral-complexity"],"author":"AINOW","created":"2024-02-15T14:05:00Z","featured":false},

    {"id":"crt-51","title":"Literary Thriller: The Document That Changes Everything","prompt":"You are a literary thriller writer. Write a 500-word scene in which protagonist Adaeze Obi, 38, a Nigerian-British archivist at the British Library, finds a document in a misfiled box that she was not supposed to find. The document itself — a letter, a photograph, a contract, a report — should be described in enough detail that the reader understands immediately what it means, even before Adaeze fully does. The scene must earn its place as the inciting incident of a thriller by: grounding the discovery in the specific, unglamorous reality of archival work; making the stakes clear without stating them; showing Adaeze's response as the response of a specific person with a specific professional identity (what does an archivist do when they find something they shouldn't have?); and ending before she has decided what to do with it.","tags":["creative-writing","literary-thriller","craft","fiction","inciting-incident"],"author":"AINOW","created":"2024-02-15T14:10:00Z","featured":false},

    {"id":"crt-52","title":"Gothic Romance: The Portrait That Lies","prompt":"You are a gothic romance writer in the tradition of Daphne du Maurier. Write the opening 600 words of a gothic romance in which the protagonist, Celia Harwick, 29, a newly hired estate archivist, first sees the portrait of the late Lady Aldermere in the Long Gallery of Thorn House, Devon. The portrait must function as: a physical object (specific, detailed, painted in a specific style in a specific year); a piece of foreshadowing for the central mystery; and a mirror for Celia — the reader should understand something about Celia's psychology from what she notices and what she projects onto the portrait. The gothic register — atmosphere, repressed desire, the uncanny, the weight of the past — should be present in every sentence without relying on gothic clichés. The portrait should lie, in a way the reader will only understand at the end of the novel.","tags":["creative-writing","gothic-romance","craft","genre-fiction","literary-fiction"],"author":"AINOW","created":"2024-02-15T14:15:00Z","featured":false},

    // --- FLASH FICTION (53-60) ---
    {"id":"crt-53","title":"Flash Fiction: 500 Words, Complete Emotional Arc","prompt":"You are a master of flash fiction and the compressed short story form. Write a complete flash fiction story of exactly 500 words that contains a full emotional arc: inciting incident, escalation, crisis, and resolution — or deliberate non-resolution that is itself a kind of resolution. The story: Marisol, 34, a pediatric nurse, receives a voicemail she wasn't meant to hear. You have 500 words. Use every one of them. No wasted sentences. The prose should feel like a precision instrument — not spare for the sake of spareness but economical because every word is doing two jobs at once. End on a specific physical image, not a statement. After the story, add a 100-word craft note identifying the three hardest compression choices you made and why.","tags":["creative-writing","flash-fiction","craft","short-story","compression"],"author":"AINOW","created":"2024-02-15T14:20:00Z","featured":true},

    {"id":"crt-54","title":"Six-Word Story Expanded: The Art of Implication","prompt":"You are a flash fiction writer and minimalism expert. Take the famous six-word story attributed to Hemingway — 'For sale: baby shoes, never worn' — as a structural model (not as content to imitate). Write six original six-word stories of equivalent emotional compression, each implying a complete tragedy, comedy, or transformation. Then take one of your six-word stories and expand it in three stages: 50 words, 200 words, 500 words. Each expansion should add specificity and depth without diluting the compression that made the six-word version work. After the expansions, write a 150-word craft analysis of what each stage of expansion added and what, if anything, it cost in terms of impact.","tags":["creative-writing","flash-fiction","craft","minimalism","workshop"],"author":"AINOW","created":"2024-02-15T14:25:00Z","featured":false},

    {"id":"crt-55","title":"Second-Person Flash Fiction: The Uncomfortable 'You'","prompt":"You are a flash fiction writer specializing in second-person narration. Write a 400-word flash fiction story in second person — 'you' as the protagonist — in which the second person creates complicity and discomfort rather than immersion and identification. The story should work because of second person, not despite it: the reader should feel implicated in something. The scenario: you are a middle manager at a tech company who has just been asked to sign off on a decision that is technically legal and thoroughly wrong. The second person should make the reader feel the specific texture of the moral compromise — not the dramatic version of it, but the ordinary, bureaucratic, Tuesday afternoon version. The story should not resolve. It should end with the cursor blinking.","tags":["creative-writing","flash-fiction","second-person","craft","ethics"],"author":"AINOW","created":"2024-02-15T14:30:00Z","featured":false},

    {"id":"crt-56","title":"The Braided Flash: Three Storylines in 600 Words","prompt":"You are a flash fiction master and structural innovator. Write a braided flash fiction of 600 words that weaves together three completely separate storylines, none of which share characters or settings, that are nonetheless thematically inseparable. The three storylines: (1) A deep-sea ROV operator watching a screen in 2031; (2) A woman in 1953 writing a letter she will never send; (3) A child burying something in a garden in an unnamed time. The braiding should not be mechanical (storyline A, then B, then C, then A again). Let the three stories interrupt each other at the points of maximum pressure. The final sentence of the piece should be a single line that belongs to all three simultaneously. After the story, write a 100-word note on the structural principle you used.","tags":["creative-writing","flash-fiction","structure","craft","braided-narrative"],"author":"AINOW","created":"2024-02-15T14:35:00Z","featured":false},

    {"id":"crt-57","title":"The Micro-Story: An Entire Life in 250 Words","prompt":"You are a flash fiction writer and compression specialist. Write a complete micro-story — 250 words exactly — that tells the entire life of a single person: from a specific formative moment in childhood to a specific moment of death. The person: Kwame Asante, a tailor in Accra, Ghana, born 1941. The 250 words must create the impression of a full human life without being a summary or a list. Use three or four specific concrete scenes — real moments, not representative generalities — and let white space and implication carry the rest. The prose should be the opposite of Wikipedia. It should feel like grief and celebration at the same time. End on the day of his death, with a specific, non-symbolic physical detail.","tags":["creative-writing","flash-fiction","micro-fiction","craft","life"],"author":"AINOW","created":"2024-02-15T14:40:00Z","featured":false},

    {"id":"crt-58","title":"The Unreliable Flash: 300 Words, Three Readings","prompt":"You are a flash fiction writer specializing in constructed ambiguity and narrative instability. Write a flash fiction of 300 words that can be read in three completely different ways depending on what the reader believes about the narrator's reliability. Version 1: the narrator is telling the complete truth and the story is a love story. Version 2: the narrator is lying and the story is a crime story. Version 3: the narrator is not lying but is profoundly wrong and the story is a tragedy. These three readings must be simultaneously available in the same 300 words — not through tricks or revealed-at-the-end mechanisms, but through genuine ambiguity built into the language itself. After the story, write a craft note identifying the specific technique used at each key ambiguous moment.","tags":["creative-writing","flash-fiction","ambiguity","craft","unreliable-narrator"],"author":"AINOW","created":"2024-02-15T14:45:00Z","featured":false},

    {"id":"crt-59","title":"Sudden Fiction: The Crisis Scene in 1,000 Words","prompt":"You are a sudden fiction writer and master of the compressed dramatic scene. Write a 1,000-word sudden fiction story in which the entire narrative takes place in a single, specific, uninterrupted moment of crisis. The moment: Magnus Reiersen, 52, a Norwegian fisherman, is on the phone with his adult son when the connection begins to break up — the son is calling from a research station in Svalbard, and the last thing Magnus hears before the line goes dead is not what you expect. The story takes place entirely inside Magnus's experience of this phone call: what he hears, what he misses, what he assumes, and the decision he makes in the three seconds of silence after the line dies. No flashback. No backstory dump. Just this moment, fully inhabited.","tags":["creative-writing","sudden-fiction","flash-fiction","craft","scene"],"author":"AINOW","created":"2024-02-15T14:50:00Z","featured":false},

    {"id":"crt-60","title":"Flash Nonfiction: The Real Moment, Rendered as Art","prompt":"You are a creative nonfiction writer specializing in flash memoir and lyric essay. Write three flash nonfiction pieces of 200 words each — each based on a different real human moment that is, on its surface, completely ordinary. The three moments: (1) Waiting for a bus in the rain; (2) The last time you spoke to someone before they died; (3) Finding something you lost years ago. These are prompts for the writer, not topics for an essay. The flash pieces should be specific (no generalities), sensory (no abstractions without concrete anchors), and should do what only nonfiction can do: let the reader feel the weight of the real. After all three, write a 100-word craft note on what transforms a real memory into flash nonfiction art.","tags":["creative-writing","flash-nonfiction","creative-nonfiction","craft","memoir"],"author":"AINOW","created":"2024-02-15T14:55:00Z","featured":false},

    // --- CREATIVE NONFICTION (61-68) ---
    {"id":"crt-61","title":"The Personal Essay: The Specific Generality","prompt":"You are a creative nonfiction writer and personal essayist in the tradition of James Baldwin, Joan Didion, and Zadie Smith. Write a 600-word opening to a personal essay about a subject that is overtly small — a specific habit, a specific object, a specific room — but that opens outward into something much larger. The subject: the ritual of making tea in a particular way. The essay must: begin with a specific, concrete, utterly particular scene (not 'I always make tea' but one specific morning, this cup, this light); use the particular to move toward the general without announcing the transition; include one unexpected intellectual turn that a reader would not predict from the opening; and maintain the voice of a specific human intelligence throughout — opinionated, self-questioning, unafraid of its own contradictions. Do not arrive at a neat conclusion. End in motion.","tags":["creative-writing","personal-essay","creative-nonfiction","craft","voice"],"author":"AINOW","created":"2024-02-15T15:00:00Z","featured":false},

    {"id":"crt-62","title":"The Lyric Essay: Fragmentation as Meaning","prompt":"You are a lyric essayist and creative nonfiction writer. Write a 700-word lyric essay in fragments on the subject of translation — not just linguistic translation but the larger idea of what is lost and what is created in any act of carrying something from one form to another. The essay must: use white space structurally, so that silence carries weight; include at least two different registers (the intimate and the analytical, or the narrative and the associative); resist the impulse to synthesize — the fragments should remain fragments, but they should resonate against each other; and include one concrete, specific narrative moment (a specific translator, a specific word, a specific failure) that anchors the abstractions. This essay should demonstrate to a student what the lyric essay can do that the traditional essay cannot.","tags":["creative-writing","lyric-essay","creative-nonfiction","craft","form"],"author":"AINOW","created":"2024-02-15T15:05:00Z","featured":false},

    {"id":"crt-63","title":"Literary Journalism: The Scene You Were In","prompt":"You are a literary journalist in the tradition of John McPhee, Tracy Kidder, and Katherine Boo. Write a 600-word opening to a piece of long-form literary journalism in which the subject is a court interpreter — specifically, Mariam Nazari, 44, who has worked as a Dari and Pashto interpreter in the UK immigration court system for fifteen years. The piece must: open on a specific scene from a specific hearing (invented, but specific enough to feel reported); render the interpreter's experience with journalistic precision and literary vividness; establish without stating it the systemic issues at play in this role; and give the reader a sense of the specific, private knowledge that Mariam carries about the stories she has interpreted — knowledge she cannot share, cannot use, and cannot forget.","tags":["creative-writing","literary-journalism","creative-nonfiction","craft","social-justice"],"author":"AINOW","created":"2024-02-15T15:10:00Z","featured":true},

    {"id":"crt-64","title":"The Memoir Scene: Then and Now","prompt":"You are a memoir writer and creative nonfiction teacher. Write a 600-word memoir scene that uses the classic memoir double timeline: the past event being narrated and the present narrator reflecting on it. The past event: a teenager, 15, having a conversation with their grandmother about the grandmother's childhood in a country that no longer exists (the specific country and history are yours to invent or adapt). The challenge of this exercise: the present narrator should add genuine insight to the past scene — not just emotional gloss ('I didn't know then what I know now') but specific knowledge gained through living that actually changes the meaning of the past. The double timeline should feel necessary. After the scene, add a 100-word craft note on the risk of the retrospective narrator and how to avoid sentimentality.","tags":["creative-writing","memoir","creative-nonfiction","craft","double-timeline"],"author":"AINOW","created":"2024-02-15T15:15:00Z","featured":false},

    {"id":"crt-65","title":"The Immersive Profile: Writing a Person Into Three Dimensions","prompt":"You are a magazine profile writer and creative nonfiction specialist. Write a 700-word profile opening for a piece about an imaginary but fully realized subject: Dr. Yinka Osei-Bonsu, 61, a Ghanaian-British entomologist who has spent thirty years studying the social organization of leafcutter ants in the Amazon basin and is now, unexpectedly, a minor celebrity because a video of her went viral. The profile opening must: begin with a scene, not a summary (show her doing something specific that reveals character); establish her intellectual world with precision and without condescension; find the central tension of her life that makes this profile interesting (what has her life cost her?); and deliver one quote from her that is so specific and strange and true that the reader will remember it.","tags":["creative-writing","profile","literary-journalism","creative-nonfiction","craft"],"author":"AINOW","created":"2024-02-15T15:20:00Z","featured":false},

    {"id":"crt-66","title":"Narrative Nonfiction: The Scene of Institutional Failure","prompt":"You are a narrative nonfiction writer specializing in systemic injustice and institutional accountability. Write a 600-word scene — reconstructed, as in literary journalism — depicting a single specific meeting in a hospital in 2019 in which a decision was made that would later contribute to a patient's preventable death. The people in the meeting are not villains. They are tired, overworked, and operating within institutional constraints that make the wrong decision the path of least resistance. Write the scene from a close third-person perspective following the most junior person in the room, the one with the least power to change the outcome. The scene must be: specific (real meeting room, real time of day, real institutional language); morally complex (no easy blame); and written so that the reader can see the exact moment where the decision was foreclosed.","tags":["creative-writing","narrative-nonfiction","creative-nonfiction","craft","institutional"],"author":"AINOW","created":"2024-02-15T15:25:00Z","featured":false},

    {"id":"crt-67","title":"The Essay That Argues Without Arguing","prompt":"You are a creative nonfiction essayist and rhetoric specialist. Write a 600-word essay that takes a clear, specific position — that something widely accepted is wrong, or that something dismissed is true — without ever making a direct argumentative claim. No thesis statement, no 'I believe,' no logical syllogism. The position must be communicated entirely through: the selection and arrangement of specific facts and observations; the juxtaposition of two or three concrete scenes; the tone and rhythm of the prose itself. The subject: the way modern cities design public space for the convenience of cars rather than the flourishing of human beings. By the end of the essay, the reader should have arrived at the position themselves, feeling as if they thought of it.","tags":["creative-writing","essay","creative-nonfiction","rhetoric","craft"],"author":"AINOW","created":"2024-02-15T15:30:00Z","featured":false},

    {"id":"crt-68","title":"Travel Writing: The Place Against Itself","prompt":"You are a literary travel writer in the tradition of Ryszard Kapuściński and Rebecca Solnit. Write a 600-word piece of travel writing about a place that resists the conventional travel writing gaze — a place that is not beautiful, not exotic, not picturesque. The place: the departure hall of a regional bus terminal in a mid-sized Eastern European city, 6 a.m. on a Tuesday in February. The writing must: render the specific sensory reality of this place with full attention and no condescension; find the genuine strangeness in the ordinary; make the reader feel that this unbeautiful place is as worthy of serious attention as any cathedral or coastline; and include one conversation, overheard or participated in, that carries the full weight of the essay's argument about place and perception.","tags":["creative-writing","travel-writing","creative-nonfiction","craft","place"],"author":"AINOW","created":"2024-02-15T15:35:00Z","featured":false},

    // --- EXPERIMENTAL WRITING (69-76) ---
    {"id":"crt-69","title":"The Constraint as Engine: Oulipo-Inspired Fiction","prompt":"You are an experimental fiction writer with expertise in constrained writing techniques in the tradition of Oulipo (Perec, Queneau, Calvino). Write a 400-word short story subject to the following constraint: every sentence must contain exactly one piece of specific numerical information (a date, a distance, a quantity, a duration, a price) — not as decoration but as load-bearing narrative fact. The story: a retired lighthouse keeper named Ivar Haugen, 74, is sorting through his dead wife's belongings the winter after her death. The numerical constraint should generate meaning, not just texture — by the end of the piece, the numbers should tell their own story inside the story. After the piece, add a 100-word note on how the constraint shaped the narrative in ways you did not anticipate.","tags":["creative-writing","experimental","constrained-writing","oulipo","craft"],"author":"AINOW","created":"2024-02-15T15:40:00Z","featured":false},

    {"id":"crt-70","title":"The Second-Person Instruction Manual as Grief","prompt":"You are an experimental literary fiction writer. Write a 500-word piece formatted as an instruction manual — numbered steps, imperative mood, technical register — but the subject is the process of grief. The form must be maintained rigorously (it must read, at the syntactic level, as an instruction manual) while the content transforms the form into something else entirely. The piece should be both funny and devastating. It should not be a parody of instruction manuals — it should be an actual instruction manual for the actual process of losing someone, and the humor should arise from the collision between the form's promise of control and the subject's radical uncontrollability. End on a step that cannot be completed.","tags":["creative-writing","experimental","form","grief","craft"],"author":"AINOW","created":"2024-02-15T15:45:00Z","featured":true},

    {"id":"crt-71","title":"The Footnote Narrative: Story in the Margins","prompt":"You are an experimental fiction writer in the tradition of David Foster Wallace and Mark Z. Danielewski. Write a 400-word piece in which two stories are told simultaneously: the main text tells one story (a formal, slightly dry account of an expedition to a remote weather station in the Canadian Arctic, 1973) and the footnotes tell a completely different, emotionally opposite story (an intensely personal, present-tense account of a specific contemporary marriage in difficulty). The footnotes should gradually overtake the main text in emotional weight. By the final footnote, the reader should be more invested in the marginal story than the main one. The main text and footnote story should never explicitly interact — only resonate.","tags":["creative-writing","experimental","form","footnote-narrative","craft"],"author":"AINOW","created":"2024-02-15T15:50:00Z","featured":false},

    {"id":"crt-72","title":"The Epistolary Story Told Through Unsent Texts","prompt":"You are an experimental fiction writer and digital narrative specialist. Write a 500-word short story told entirely through the draft messages folder of a single character's phone — texts written but never sent. The character: Phoebe, 27, a graphic designer who has just discovered that her closest friend of twelve years has been lying to her about something significant. The draft messages are addressed to: the friend, her mother, her therapist, a stranger whose number she found on a lost phone two years ago and has been drafting messages to ever since. The story must have a complete arc. The reader must understand, through the drafts alone, what happened, what Phoebe has decided, and who she is. Nothing is sent. The final draft is never completed.","tags":["creative-writing","experimental","epistolary","digital-narrative","fiction"],"author":"AINOW","created":"2024-02-15T15:55:00Z","featured":false},

    {"id":"crt-73","title":"The Negative Space Story: Telling It by Omission","prompt":"You are an experimental fiction writer specializing in narrative omission and negative space. Write a 400-word short story from which the central event has been entirely removed — the story is told entirely through what happened before and after, with a deliberate blank at the center. The reader must be able to reconstruct the central event precisely, but it must never be named or shown. The event: a confession, made by an adult child to an aging parent, about something that happened thirty years ago. The before: a car journey to the parent's home. The after: the car journey back. The blank in the middle: the conversation itself. The before and after must each be transformed by the blank between them, so the reader feels the event as a seismic shift in the prose's emotional register.","tags":["creative-writing","experimental","omission","craft","literary-fiction"],"author":"AINOW","created":"2024-02-15T16:00:00Z","featured":false},

    {"id":"crt-74","title":"Metafiction: The Character Who Knows","prompt":"You are a metafiction writer and postmodern literary specialist. Write a 500-word short story in which the protagonist, halfway through the story, becomes aware that they are in a story. The challenge: this must not be played for comedy or as mere postmodern game-playing. The character's awareness of their fictional status must become the vehicle for genuine emotional inquiry. What does it mean to know that your story has already been written? What does choice mean for a character who knows they are being read? The protagonist: Selene, a middle-aged woman who has, in the story's first half, been making a difficult decision about whether to stay in a marriage. The moment of metafictional awareness should arise naturally from the narrative's emotional pressure, not from a trick.","tags":["creative-writing","experimental","metafiction","craft","literary-fiction"],"author":"AINOW","created":"2024-02-15T16:05:00Z","featured":false},

    {"id":"crt-75","title":"The Chorus Narrator: Community as Voice","prompt":"You are a literary fiction writer specializing in collective and communal narration. Write a 500-word opening to a literary novel narrated in the first-person plural — 'we' — by the community of a small fishing village on the Adriatic coast. The 'we' must feel genuinely collective (not one person ventriloquizing a community) — show the fractures within the we, the disagreements, the moments when the we becomes 'most of us' or 'some of us.' The inciting event: a young woman from the village has returned after fifteen years, and she has brought someone with her no one expected. The chorus narration should reveal what the community collectively knows, collectively fears, and collectively will not say. End on a sentence where the 'we' fragments for the first time.","tags":["creative-writing","experimental","chorus-narrator","literary-fiction","craft"],"author":"AINOW","created":"2024-02-15T16:10:00Z","featured":false},

    {"id":"crt-76","title":"Prose Poetry: The Threshold Moment","prompt":"You are a prose poet and literary fiction writer working at the boundary of the two forms. Write five prose poems — each 80–120 words — each capturing a different kind of threshold moment: the moment before a door is opened, the moment between sleep and waking, the moment a word is about to be spoken that will change everything, the moment of the last breath of something, the moment a child first understands that adults do not know everything. Each prose poem should have the compression and imagistic intensity of poetry with the syntactic freedom of prose. No rhyme. No obvious line breaks imported into prose. Each piece should be complete in itself and should demonstrate a different technique for how prose can do what poetry does.","tags":["creative-writing","experimental","prose-poetry","craft","lyric"],"author":"AINOW","created":"2024-02-15T16:15:00Z","featured":false},

    // --- DIALOGUE & SCENE CRAFT (77-84) ---
    {"id":"crt-77","title":"The Dialogue That Buries the Lede","prompt":"You are a fiction writer and dialogue specialist. Write a 400-word scene consisting almost entirely of dialogue between two people — Nadia, 38, and her brother Eli, 45 — who are sorting through their parents' belongings after their mother's death. The scene must demonstrate the technique of 'burying the lede': the most important thing — the thing the entire scene is actually about — should not be mentioned until the very last line of dialogue, and the reader should not feel cheated by this, because every exchange before it was, in retrospect, approaching that thing at an angle. The topic of conversation for most of the scene should be entirely mundane (what to do with the kitchen things, who wants the record player). The final line should land like a door closing.","tags":["creative-writing","dialogue","craft","scene","fiction"],"author":"AINOW","created":"2024-02-15T16:20:00Z","featured":false},

    {"id":"crt-78","title":"Action Beats as Character Revelation","prompt":"You are a fiction writer and scene construction specialist. Write a 400-word scene of dialogue between two characters — a senior surgeon, Dr. Ravi Mehta, 58, and a junior resident, Dr. Priya Osman, 29 — in which you use only action beats (no dialogue tags, no interior monologue) to reveal the power dynamic, the emotional subtext, and the history between them. No 'he said said warmly,' no 'she felt her face flush.' Only what each character does with their body — with their hands, their eyes, their physical relationship to the space — while the other speaks. The dialogue itself should be entirely about a patient case. The action beats alone should tell the real story. This exercise should demonstrate to a writer how much characterization can live in physical behavior.","tags":["creative-writing","dialogue","action-beats","craft","scene"],"author":"AINOW","created":"2024-02-15T16:25:00Z","featured":false},

    {"id":"crt-79","title":"The Three-Way Conversation Where No One Is Honest","prompt":"You are a literary fiction writer. Write a 500-word scene featuring a three-way conversation between Camille, 42, her ex-husband Pierre, 46, and their shared friend Lena, 43, who they have asked to mediate a discussion about their adult son's upcoming wedding, at which both parents must be present. All three characters know something the others do not, and no one tells the truth. Camille knows that their son has specifically asked her to attend alone but hasn't told Pierre. Pierre knows he is seeing Lena romantically but neither has told Camille. Lena knows both of these things. Write the conversation so that each character's deception is visible to the reader in their word choices and evasions while remaining invisible to the other characters. The scene should be both comic and painful.","tags":["creative-writing","dialogue","scene","deception","literary-fiction"],"author":"AINOW","created":"2024-02-15T16:30:00Z","featured":false},

    {"id":"crt-80","title":"Scene Construction: The 360-Degree Room","prompt":"You are a fiction writing professor and scene construction expert. Write a 500-word scene that gives the reader a complete, three-dimensional sense of a single room — its physical reality, its emotional atmosphere, and its narrative significance — through the consciousness of a single character entering it for the first time. The character: Tomasz Nowak, 55, a building inspector who has been sent to assess a property that has been empty for nine years. The room is a child's bedroom. The challenge: do not begin with a physical description of the room. Let the room build through Tomasz's specific noticing — what he notices first, what he circles back to, what he doesn't look at directly, and what one detail makes him pause in a way he cannot explain. End on a professional judgment. The emotional judgment should be unreachable.","tags":["creative-writing","scene","setting","craft","fiction"],"author":"AINOW","created":"2024-02-15T16:35:00Z","featured":false},

    {"id":"crt-81","title":"Dialogue Workshop: The Fight That Isn't About What It's About","prompt":"[Paste your dialogue draft or describe the two characters and their situation]\n\nYou are a fiction editor and dialogue specialist. Review the dialogue or character situation above and write a 500-word model scene demonstrating the technique of displacement: a fight between two characters in which the stated subject (what they are arguing about on the surface) is completely different from the real subject (what they are actually fighting about underneath). The surface: a couple arguing about whether to buy a new car. The real subject: one of them is losing confidence in the future they planned together. Rules: the real subject must never be named directly; the surface argument must be real and specific, not just a transparent metaphor; the moment where the real subject briefly surfaces and is immediately covered up should happen once, in the middle, and the reader should feel it like a skip in the record.","tags":["creative-writing","dialogue","craft","workshop","subtext"],"author":"AINOW","created":"2024-02-15T16:40:00Z","featured":false},

    {"id":"crt-82","title":"The Monologue That Reveals Everything","prompt":"You are a theater-trained fiction writer. Write a 400-word dramatic monologue for the stage — a character speaking directly, without interruption, to another character who does not respond. The speaker: Grace Mbeki, 66, a Zimbabwean-born academic in Edinburgh, speaking to her adult daughter who is leaving for a position in New York. The monologue must: sound like real speech (with its repetitions, its self-corrections, its sudden changes of direction) while functioning as highly crafted literary writing; reveal, through what Grace says and how she says it, both what she is consciously trying to communicate and what she is unconsciously revealing; contain one thing she has never said before; and end mid-thought, on an incomplete sentence that the daughter finishes in silence. Write stage directions only for entrances and exits.","tags":["creative-writing","monologue","drama","craft","character"],"author":"AINOW","created":"2024-02-15T16:45:00Z","featured":false},

    {"id":"crt-83","title":"Writing Silence: The Scene Where Nothing Is Said","prompt":"You are a literary fiction writer specializing in the narrative use of silence and omission. Write a 400-word scene in which the most important communication happens in the silences between the dialogue — in the pauses, the interrupted sentences, the things that are started and stopped, and the specific physical behaviors that fill the gaps. The scene: two old friends, Omar and James, who have not spoken in three years, meet by accident on a train between Edinburgh and Glasgow. They have exactly 47 minutes. They talk about everything except the reason they stopped speaking. Write the scene so that the reader can feel the shape of what is not said — its weight, its specific topography — without it ever being named. The train pulling into Queen Street Station ends the scene and the opportunity simultaneously.","tags":["creative-writing","dialogue","silence","craft","literary-fiction"],"author":"AINOW","created":"2024-02-15T16:50:00Z","featured":false},

    {"id":"crt-84","title":"The Scene Editor's Report: Diagnosing Dialogue Problems","prompt":"[Paste your dialogue scene]\n\nYou are a senior fiction editor with 25 years of experience. Read the scene above and produce a scene editor's report covering:\n\n1. DIFFERENTIATION: Do the characters sound like individuals or like different versions of the same voice? Quote two lines where differentiation fails and rewrite them.\n2. SUBTEXT RATIO: What percentage of what is actually being communicated is said directly, and what percentage is subtext? Is the ratio right for this scene's emotional moment?\n3. RHYTHM: Read the dialogue aloud (mentally). Where does the rhythm become mechanical — lines of similar length stacking up, beats landing at predictable intervals? Identify and revise one passage.\n4. THE TAG PROBLEM: Are dialogue tags working or decorating? Identify every 'adverb tag' and suggest whether to cut or convert it to an action beat.\n5. THE EXIT: Does the scene end or stop? Recommend a specific revision to the final line.","tags":["creative-writing","editing","dialogue","workshop","craft"],"author":"AINOW","created":"2024-02-15T16:55:00Z","featured":false},

    // --- CREATIVE PROCESS & WORKSHOP (85-92) ---
    {"id":"crt-85","title":"Breaking Writer's Block: The Oblique Entry","prompt":"You are a creative writing coach specializing in generative techniques and blocked writers. I am stuck on a specific project and cannot find a way in. Use the following oblique entry technique to help me generate new material: instead of approaching the blocked scene or chapter directly, generate five completely different entry points to the same narrative moment — five different 'ways in' that approach the scene from an unexpected angle. The blocked scene: [describe your blocked scene or chapter in 2-3 sentences]. The five entry points should each use a different strategy: one begins with a peripheral character who is not in the scene; one begins with a physical object; one begins at a different time (before or after); one begins with a sound; one begins with a question the protagonist cannot answer. Write 100 words for each entry point.\n\n[Describe your blocked scene]","tags":["creative-writing","writers-block","workshop","process","generative"],"author":"AINOW","created":"2024-02-15T17:00:00Z","featured":false},

    {"id":"crt-86","title":"The 30-Day Novel: Structural Scaffolding","prompt":"You are a novel-writing coach and structural specialist. Help me build a complete structural scaffold for a 80,000-word novel in 30 writing days, working from the following premise: [describe your novel premise in 3-5 sentences]. The scaffold should include: (1) A chapter-by-chapter outline broken into four sections corresponding to a four-act structure; (2) The five 'load-bearing scenes' — the scenes where the most important structural work happens — with specific guidance on what each must accomplish; (3) A daily word-count plan that accounts for the reality of uneven writing days; (4) Three 'in-case-you're-lost' diagnostic questions to ask at any point during drafting; (5) A pre-writing exercise for the first writing day that will help me find the protagonist's voice before writing chapter one.\n\n[Describe your novel premise]","tags":["creative-writing","novel","planning","workshop","process"],"author":"AINOW","created":"2024-02-15T17:05:00Z","featured":false},

    {"id":"crt-87","title":"The Line Edit: Prose at the Sentence Level","prompt":"[Paste a paragraph of your prose]\n\nYou are a line editor with deep expertise in sentence-level prose craft. Perform a thorough line edit on the paragraph above. For every change you suggest, explain the craft principle behind it. Look specifically for:\n- Passive constructions that diffuse energy (identify whether each is justified or not)\n- Adjectives that tell rather than show (cut or replace?)\n- Abstract nouns where concrete nouns would do more work\n- Sentence rhythm: where does the paragraph breathe correctly, and where does it hold too long or cut too short?\n- The relationship between sentence length and emotional pacing\n- Any word used more than once in a short passage\n\nProvide: the original paragraph, a fully line-edited version, and a sentence-by-sentence annotation of your key decisions. Do not over-edit. The writer's voice must survive.","tags":["creative-writing","editing","line-edit","craft","workshop"],"author":"AINOW","created":"2024-02-15T17:10:00Z","featured":true},

    {"id":"crt-88","title":"Finding the Theme: What Your Story Is Actually About","prompt":"[Paste a synopsis or first chapter of your work in progress]\n\nYou are a literary editor and story analyst. Read the synopsis or excerpt above and identify what the story is actually about — not its plot (what happens) but its theme (what it means, what human truth it is investigating). Many writers don't know their theme until they are deep in the first draft, and this is fine — but identifying it can transform revision. Provide: (1) Three possible thematic readings of this material, ranging from the most literal to the most resonant; (2) For each theme, identify two scenes from the synopsis that support it and one scene that currently undermines it; (3) A recommendation for which thematic direction will produce the most interesting, specific, lasting work — with a rationale; (4) One question to ask yourself about every scene in the revision: does this scene illuminate, complicate, or deepen the theme?","tags":["creative-writing","theme","editing","workshop","craft"],"author":"AINOW","created":"2024-02-15T17:15:00Z","featured":false},

    {"id":"crt-89","title":"The Writing Workshop Critique: Generous and Precise","prompt":"[Paste a short story or excerpt for workshop]\n\nYou are a creative writing workshop leader facilitating an MFA-level workshop critique. Provide a full workshop response to the piece above following the best practices of the workshop format: lead with what is working and why, with specific textual evidence; identify the central craft challenge the piece is wrestling with and characterize it generously; offer three specific, actionable revision suggestions (not direction but specific technique); identify the strongest single sentence and explain why it works; identify the passage that most needs revision and offer two alternative approaches; end with the central question this piece is trying to answer and whether the current draft answers it. The critique should be honest, specific, and in service of the writer's vision — not the critic's.","tags":["creative-writing","workshop","critique","editing","craft"],"author":"AINOW","created":"2024-02-15T17:20:00Z","featured":false},

    {"id":"crt-90","title":"The Revision X-Ray: Diagnosing First-Draft Problems","prompt":"[Paste your first draft chapter or scene]\n\nYou are a developmental editor specializing in first-draft diagnosis. Apply the 'revision X-ray' to the draft above: a systematic scan that identifies structural problems invisible to the writer at this stage. Scan for:\n\n1. THE ENERGY MAP: Mark each paragraph H (high energy), M (medium), or L (low). Is the distribution serving the scene's dramatic needs?\n2. THE INFORMATION AUDIT: Identify every piece of information introduced in this draft. Is each piece introduced at the right moment, or is the writer front-loading backstory?\n3. THE DESIRE LINE: Can you identify, in a single sentence, what the POV character wants in every paragraph? Where does the desire line go slack?\n4. THE SCENE QUESTION: Every scene should raise a question in the reader's mind by the end of the first page. What is the question here, and is it the right one?\n5. THE DRAFT PROMISE: What does this draft promise the reader for the rest of the story? Is that the promise you want to make?","tags":["creative-writing","revision","editing","workshop","craft"],"author":"AINOW","created":"2024-02-15T17:25:00Z","featured":false},

    {"id":"crt-91","title":"Building a Writing Practice: The Personal System","prompt":"You are a creative writing coach who works with writers at all stages of their careers. Help me design a sustainable, realistic writing practice suited to my specific situation. I am a writer who: [describe your life situation — available hours per week, whether you have a specific project underway, your biggest obstacles, what you have tried before]. Design: (1) A daily or weekly writing schedule that is ambitious but survivable — not a fantasy of seven-hour writing days but an actual system for an actual human life; (2) Specific strategies for the three most common obstacles you identify in my description; (3) A set of 'warming-up' exercises suited to my stage and project; (4) How to use limited time on the days when there is very little (30 minutes or less); (5) How to return to the work after an extended absence without losing momentum.\n\n[Describe your writing situation]","tags":["creative-writing","process","practice","workshop","craft"],"author":"AINOW","created":"2024-02-15T17:30:00Z","featured":false},

    {"id":"crt-92","title":"The Rejection Analysis: What the Form Letter Isn't Telling You","prompt":"[Paste or describe the story/excerpt that was rejected, with any feedback received]\n\nYou are a literary agent and former fiction editor who has worked in publishing for twenty years. Analyze the rejected piece above — or as much of it as I've shared — and give me your honest professional assessment of the most likely reasons for rejection. Do not soften this. Be specific: identify whether the issue is in the opening pages, the premise, the execution, the voice, the market fit, or some combination. For each issue identified: (1) Explain why this would be a dealbreaker for an agent or editor; (2) Suggest a specific revision strategy; (3) Identify at least one comparable published work that solved a similar problem well and explain how. Finish with a realistic assessment: is this piece revise-and-resubmit worthy, or would the writer's time be better spent on a new project?","tags":["creative-writing","publishing","rejection","craft","workshop"],"author":"AINOW","created":"2024-02-15T17:35:00Z","featured":false},

    // --- VOICE DEVELOPMENT (93-100) ---
    {"id":"crt-93","title":"Finding Your Voice: The Authenticity Excavation","prompt":"You are a creative writing coach specializing in voice development. Help me excavate and define my authentic writing voice using the following process. I will share three pieces of my own writing — ideally from different periods or projects. [Paste up to three short excerpts of your own writing.] Analyze across all three pieces: (1) Identify the consistent qualities — of syntax, rhythm, imagery, tonal register — that appear in all three, even if I am not conscious of them; (2) Identify the qualities that feel forced or borrowed — the places where I am imitating a style rather than speaking in my own; (3) Define, in specific craft terms (not vague praise), what my natural voice does well; (4) Suggest two exercises to push that voice into greater distinctiveness; (5) Name three published writers whose voices have affinities with mine and explain what that means for my reading practice.\n\n[Paste your writing excerpts]","tags":["creative-writing","voice","craft","workshop","development"],"author":"AINOW","created":"2024-02-15T17:40:00Z","featured":true},

    {"id":"crt-94","title":"Style Dissection: How This Author Does What They Do","prompt":"You are a literary critic and prose style analyst. Dissect the prose style of Marilynne Robinson's novel Gilead — specifically, the technique of the long, meditative sentence that carries multiple subordinate clauses and still arrives at emotional clarity. Identify: (1) The specific syntactic structure of a Robinson sentence at its most characteristic — name the grammatical features; (2) How she manages to be simultaneously abstract and precise; (3) The relationship between sentence rhythm and the narrator's emotional state; (4) The way her prose earns its religious vocabulary without alienating secular readers; (5) What a writer who admires this style should study and what they should resist imitating. This analysis should function as a masterclass in close reading of style, applicable to any writer who wants to learn from an existing voice without being consumed by it.","tags":["creative-writing","style","craft","analysis","literary-criticism"],"author":"AINOW","created":"2024-02-15T17:45:00Z","featured":false},

    {"id":"crt-95","title":"The Voice that Carries Trauma Without Performing It","prompt":"You are a literary fiction writer and creative writing professor with expertise in writing about trauma with craft and restraint. Write a 500-word scene from the perspective of a character — Kenji, 42, a Japanese-American former marine — who experienced something catastrophic and who does not discuss it, does not reflect on it directly, and does not display conventional signs of PTSD as rendered in lesser fiction. The trauma must be present in the scene — it must shape every word Kenji speaks and every choice he makes — but it must be present the way a past wound shapes a body: in the posture, in the movement, in the specific ways certain things are approached and avoided. The scene: Kenji is teaching his twelve-year-old niece to drive in an empty parking lot on a Sunday morning. Write it straight.","tags":["creative-writing","voice","trauma","craft","literary-fiction"],"author":"AINOW","created":"2024-02-15T17:50:00Z","featured":false},

    {"id":"crt-96","title":"The Comic Voice: Precision as the Source of Humor","prompt":"You are a comic literary fiction writer in the tradition of Evelyn Waugh, Muriel Spark, and early Martin Amis. Write a 500-word scene demonstrating that the highest form of comic writing comes not from jokes but from extreme precision applied to absurd situations. The scene: a departmental meeting at a third-tier British university in which the English Literature faculty are debating, with full academic seriousness, whether to rename the department to include 'and Creative Writing' in its title — a debate that has now entered its third hour and fourth year. The comedy must come from: specificity of character (each person's particular form of self-interest and self-delusion); precision of language (the gap between the register of the discourse and the pettiness of the stakes); and one moment of genuine human feeling that the comic frame makes devastating. No punchlines. No italics for emphasis.","tags":["creative-writing","comedy","voice","craft","literary-fiction"],"author":"AINOW","created":"2024-02-15T17:55:00Z","featured":false},

    {"id":"crt-97","title":"The Lyric Voice: When Fiction Touches Poetry","prompt":"You are a literary fiction writer and prose stylist working at the boundary of fiction and poetry. Write a 500-word prose passage — not a poem, not a story, but a piece of lyric prose — in which the primary purpose is not to advance narrative or build character but to render a single experience with such precision and beauty that the prose itself becomes the experience. The subject: the specific quality of light in a city at 5 a.m. in late September — not any city but a specific one: Lisbon, in the Alfama district, in a year of particular drought. The passage should demonstrate what lyric prose can do that neither poetry nor narrative fiction can do separately: it should have the compression and image-density of poetry with the physical groundedness and temporal specificity of fiction. No plot. No characters. Just the light.","tags":["creative-writing","lyric-prose","voice","craft","experimental"],"author":"AINOW","created":"2024-02-15T18:00:00Z","featured":false},

    {"id":"crt-98","title":"Developing Your Dialogue Voice: The Signature Line","prompt":"You are a dialogue coach and fiction writer. Help me develop a distinctive dialogue voice for my protagonist [describe your protagonist in 2-3 sentences]. Great characters speak in ways that are recognizably and exclusively theirs — not through accent or catchphrase but through a particular grammar of thought: what they choose to respond to, what they deflect, the length and structure of their sentences, the specific things they reach for when they need a metaphor. Using my character description, generate: (1) Ten sample lines of dialogue that could only be spoken by this character — test them by asking whether any other character in the novel could plausibly say the same thing; (2) A 'dialogue voice document' — a one-page character reference describing this character's speech patterns so I can maintain consistency across a long manuscript; (3) One 'tell' — a linguistic habit that will function as a character signature throughout the book.\n\n[Describe your protagonist]","tags":["creative-writing","dialogue","voice","workshop","character"],"author":"AINOW","created":"2024-02-15T18:05:00Z","featured":false},

    {"id":"crt-99","title":"The Prose Rhythm Workshop: Sentence as Music","prompt":"You are a prose stylist and creative writing professor. Teach me to hear and control the rhythm of my prose using the following framework. First, explain the three core rhythmic modes in literary prose (not poetic meter but prose rhythm): the accumulative sentence (that builds through addition), the periodic sentence (that withholds its meaning until the end), and the freight-train sentence (that moves through coordinating conjunctions). Write a 100-word demonstration of each mode using the same subject matter (a woman crossing a street in the rain). Then take the following passage from my own writing: [paste a paragraph]. Scan its rhythm — mark the stressed and unstressed syllables in three representative sentences and describe what rhythmic pattern is dominant. Suggest one revision that would introduce rhythmic variation without changing meaning. Explain what that variation does emotionally.","tags":["creative-writing","prose-rhythm","style","craft","workshop"],"author":"AINOW","created":"2024-02-15T18:10:00Z","featured":false},

    {"id":"crt-100","title":"The Complete Short Story: From Premise to Final Draft Roadmap","prompt":"You are a master short story writer and creative writing professor who has published and taught the form for thirty years. I want to write a short story and I have only a premise: [describe your premise in 1-3 sentences]. Guide me through the complete development of this story from premise to final draft using the following stages: (1) PREMISE INTERROGATION — push the premise until it reveals its real subject: ask me three questions that will take the premise from what it is about to what it is really about; (2) THE FIRST DECISION — recommend the POV, tense, and narrative distance that will best serve this particular story, with a rationale; (3) THE STRUCTURAL SKETCH — outline the story in five beats, identifying what must happen at each beat and why; (4) THE OPENING — write the first 200 words as a model first draft, demonstrating the voice and entry point you recommend; (5) THE REVISION QUESTION — identify the one question I must be able to answer before I can revise this story from first draft to final.\n\n[Describe your story premise]","tags":["creative-writing","short-story","craft","workshop","complete-process"],"author":"AINOW","created":"2024-02-15T18:15:00Z","featured":true}

];
  __exports.creativePrompts = creativePrompts;
})();